export default "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"color-scheme\" content=\"light\">\n<title>Campus App</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,400;0,500;0,700;1,900&display=swap\" rel=\"stylesheet\">\n<style>\n:root{color-scheme:light;--red:#e01e26;--sal:#f7a692;--pink:#fde4e1;--bg:#fcf6fa;--pbg:#fdf1ef;--card:#fff;--tx:#2f3a4a;--mut:#6b7280;--sk:#e8e4e6;--ln:#e6d9d9}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml{height:100%;scroll-padding-top:env(safe-area-inset-top,0px)}\nbody{height:100%;margin:0;font-family:Roboto,system-ui,sans-serif;background:var(--bg);color:var(--tx);display:flex;justify-content:center}\nbutton{font:inherit;cursor:pointer}\n#app{position:relative;width:100%;max-width:min(560px,calc(100vh*.47));height:100%;overflow:hidden;overflow:clip;background:var(--bg);--d:1}\n#top{position:absolute;top:0;left:0;right:0;z-index:5;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:space-between;padding:calc(env(safe-area-inset-top,0px) + 4px) 14px 4px;height:calc(56px + env(safe-area-inset-top,0px))}\n#top button{background:none;border:0;color:#fff;padding:6px}\n.wm{font-weight:900;font-style:italic;letter-spacing:-.5px;line-height:1;text-align:center}\n.wm small{display:block;font:700 6px Roboto;font-style:normal;letter-spacing:0;margin-top:2px}\n.brand-logo{display:block;object-fit:contain}\n#hw .brand-logo{width:98px;height:56px}\n#dw .brand-logo{width:190px;height:auto;margin-bottom:20px}\n.pg{position:absolute;inset:0;overflow-y:auto;padding-bottom:100px;display:none}\n.pg.on{display:block;animation:in .35s ease both}\n@keyframes in{from{opacity:0;transform:translateX(calc(var(--d)*36px))}}\n#home{padding-top:calc(56px + env(safe-area-inset-top,0px))}\n.wsw{container-type:inline-size}\n.ws{position:relative;height:100cqw;overflow:hidden}\n.wh{position:absolute;top:49.5%;width:0;height:0;touch-action:none;user-select:none;-webkit-user-select:none}.wl{left:0}.wr{right:-.9cqw}\n.dsk{position:absolute;width:39.3cqw;height:39.3cqw;left:-19.65cqw;top:-19.65cqw;border-radius:50%;background:#fee2e1}\n.wr .dsk{width:43.6cqw;height:43.6cqw;left:-21.8cqw;top:-21.8cqw}\n.wc{position:absolute;top:-6.5cqw;width:22cqw;color:var(--mut);font-size:3.2cqw;letter-spacing:.2cqw;white-space:nowrap}\n.wl .wc{left:-6.8cqw;text-align:right}.wr .wc{right:auto;left:-19.6cqw;text-align:left}\n.wc b{display:block;font-size:8.4cqw;color:var(--red);letter-spacing:0;line-height:1.1}\n.wheel{position:absolute;left:0;top:0;width:0;height:0;transform:rotate(var(--turn,0deg));transform-origin:0 0;transition:transform .24s cubic-bezier(.2,.75,.25,1);pointer-events:none}\n.tl{position:absolute;left:0;top:0;width:20.5cqw;height:10cqw;margin:-5cqw 0 0 -10.25cqw;transform:rotate(var(--a)) translateX(33cqw);background:linear-gradient(#f9b09d,#f5a08a);border-radius:1.2cqw 3cqw 3cqw 1.2cqw;box-shadow:0 0 0 .5cqw #ffffffa0,0 1cqw 2cqw #0003;display:grid;place-items:center;font-size:3.6cqw;color:#40302f;white-space:nowrap;animation:spin .7s both;animation-delay:calc(var(--i)*30ms)}\n.tl{pointer-events:auto;cursor:grab}\n.tl span{display:block;transform:rotate(var(--f))}\n@keyframes spin{from{opacity:0;transform:rotate(calc(var(--a) - 70deg)) translateX(19cqw)}}\n.cwo{container-type:inline-size;margin:min(6.6vw,37px) 5% 0;perspective:1200px}\n.flip{position:relative;aspect-ratio:2.54;transform-style:preserve-3d;touch-action:none;user-select:none;-webkit-user-select:none;cursor:grab}\n.fc{position:absolute;inset:0;border-radius:2.5cqw;overflow:hidden;backface-visibility:hidden;-webkit-backface-visibility:hidden;box-shadow:0 .8cqw 2cqw #0003}\n.fr{background:var(--sal);color:#3b2b2b}\n.ring{position:absolute;inset:0;background:radial-gradient(circle at 16.1cqw 50%,#fff 0 14.2cqw,var(--red) 14.2cqw 17.9cqw,#fff 17.9cqw 23.6cqw,#0000 23.6cqw)}\n.ph{position:absolute;left:1.9cqw;top:calc(50% - 14.2cqw);width:28.4cqw;height:28.4cqw;border-radius:50%;overflow:hidden;border:.9cqw solid #fff}\n.avs svg,.avs img{width:100%;height:100%;display:block;object-fit:cover}\n.si{position:absolute;left:0;right:4cqw;top:5.1cqw;text-align:right;font-size:4.1cqw;line-height:1.3}\n#cc{font-size:3.6cqw}\n.pill{margin-left:49cqw;background:#fde9e4;border-radius:5cqw 0 0 5cqw;padding:.8cqw 3cqw;line-height:1.15;text-align:center;font-weight:700;font-size:4.6cqw;margin-right:-4cqw;margin-bottom:1.5cqw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tap{position:absolute;right:0;bottom:0;width:15.4cqw;height:9.8cqw;background:var(--red);color:#fff;border:0;border-radius:5cqw 0 1.5cqw 5cqw;font-size:4.2cqw;font-weight:500}\n.bk2{background:var(--card);transform:rotateX(180deg);padding:3.4cqw 4cqw;font-size:3.7cqw;line-height:1.55;color:var(--tx);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.eb{position:absolute;right:3cqw;bottom:2.5cqw;background:none;border:1px solid var(--red);color:var(--red);border-radius:3cqw;padding:.8cqw 3cqw;font-size:3.3cqw}\n.sk{background:linear-gradient(100deg,var(--sk) 30%,#ffffff99 50%,var(--sk) 70%);background-size:300% 100%;animation:sh 1.3s linear infinite}\n@keyframes sh{to{background-position:-300% 0}}\n.sks{display:none}.ld>.real{display:none}.ld>.sks{display:block}\n#nav{position:absolute;left:0;right:0;bottom:0;z-index:6;height:60px}\n#nav .bar{position:absolute;inset:0;width:100%;height:100%;filter:drop-shadow(0 -2px 5px #0002)}\n#nav .knob{position:absolute;top:-5px;width:44px;height:44px;display:grid;place-items:center;color:#e5326f}\n#nav .row{position:absolute;inset:0 0 9px 0;display:grid;grid-template-columns:repeat(4,1fr)}\n#nav .row button{background:none;border:0;color:#fff}\n#nav .row button.on svg{opacity:0}\n#prof{background:var(--pbg);padding-top:env(safe-area-inset-top,0px)}\n.t1{padding:16px 16px 6px;font-size:18px}\n.hero{position:relative;height:150px;background:var(--card);margin-top:4px}\n.hello{position:absolute;right:0;top:0;left:90px;text-align:right;padding:10px 16px;font-size:14px;background:var(--pbg);border-radius:0 0 0 22px;margin:0}\n.blob{position:absolute;left:-40px;top:22px;width:200px;height:112px;border-radius:60px;background:#fbd9d6}\n.blob::after{content:\"\";position:absolute;inset:12px 20px 12px 52px;border-radius:50px;background:#fde8e6}\n.av{position:absolute;left:22px;top:22px;width:104px;height:104px;border-radius:50%;border:4px solid #fff;box-shadow:0 0 0 4px #f6c4be;overflow:hidden;z-index:1}\n.lk{display:flex;justify-content:space-between;background:var(--card);padding:6px 24px 14px;font-size:12px}\n.lk button{background:none;border:0;color:var(--tx);display:flex;gap:4px;align-items:center;padding:0}\n.sheet{background:var(--pbg);border-radius:26px 26px 0 0;padding:16px 14px 20px;margin-top:-10px;position:relative}\n.tabs{display:flex;gap:26px;justify-content:center}\n.tabs button{border:0;border-radius:10px;padding:9px 14px;color:#fff;background:#bdbdbd;box-shadow:0 3px 6px #0003;font-size:13px;transition:background .25s}\n.tabs button.on{background:var(--sal)}\n.sheet h3{font-weight:500;font-size:17px;margin:18px 0 10px}\n.ir{display:flex;gap:14px;align-items:center;background:var(--card);border-radius:12px;padding:10px 14px;margin-bottom:10px;box-shadow:0 2px 6px #00000014;color:var(--red)}\n.ir small{display:block;color:var(--mut);font-size:11px;letter-spacing:.4px}.ir div{color:var(--tx);font-size:14px;min-height:18px}\n.fab{position:absolute;right:16px;bottom:calc(78px + env(safe-area-inset-bottom,0px));z-index:4;background:var(--sal);color:#fff;border:0;border-radius:14px;padding:10px 16px;display:flex;gap:8px;align-items:center;box-shadow:0 3px 8px #0004;font-size:13px}\n#ep{position:absolute;inset:0;z-index:20;background:var(--pbg);overflow-y:auto;transform:translateX(100%);transition:transform .35s cubic-bezier(.3,.8,.3,1)}\n#ep.on{transform:none}\n.eh{position:sticky;top:0;z-index:2;background:var(--pbg);padding:calc(env(safe-area-inset-top,0px) + 12px) 14px 8px;display:flex;align-items:center;gap:10px}\n.bk{width:36px;height:36px;border-radius:50%;border:1px solid var(--red);background:none;color:var(--red);display:grid;place-items:center;flex:none}\n.eh h2{margin:0;font-weight:400;flex:1;text-align:center;font-size:var(--fs,32px);padding-right:36px}\n.pc{display:flex;flex-direction:column;align-items:center;gap:6px;margin:6px 0 4px;font-size:13px;color:var(--red);cursor:pointer}\n.pc .avs{width:88px;height:88px;border-radius:50%;overflow:hidden;border:3px solid #fff;box-shadow:0 0 0 3px #f6c4be}\n.f{position:relative;margin:12px 16px}\n.f input,.f select{width:100%;padding:20px 14px 8px;border:1px solid var(--ln);border-radius:12px;background:var(--card);font:16px Roboto,sans-serif;color:var(--tx);outline:0;height:54px}\n.f input:focus,.f select:focus{border-color:var(--red)}\n.f label{position:absolute;left:14px;top:6px;font-size:11px;color:var(--mut);pointer-events:none;transition:all .15s}\n.f input:placeholder-shown:not(:focus)+label{top:17px;font-size:16px}\n.f select{appearance:none;padding-top:22px}\n.sub{margin:18px 16px 0;font-size:14px}\n.sv{display:block;margin:22px auto;border:0;border-radius:20px;background:#ece6f6;color:#4b3b6b;padding:10px 28px;box-shadow:0 2px 5px #0003}\n#dr{position:absolute;inset:0;z-index:30;pointer-events:none}\n#dr i{position:absolute;inset:0;background:#0006;opacity:0;transition:opacity .3s}\n#dr nav{position:absolute;left:0;top:0;bottom:0;width:78%;background:var(--card);transform:translateX(-100%);transition:transform .3s;padding:calc(env(safe-area-inset-top,0px) + 24px) 20px}\n#dr.on{pointer-events:auto}#dr.on i{opacity:1}#dr.on nav{transform:none}\n#dr nav a{display:block;padding:14px 4px;border-bottom:1px solid var(--ln);font-size:15px}\n#sp{position:absolute;inset:0;z-index:50;background:#fff;display:grid;place-items:center;transition:opacity .5s}\n#sp>*{grid-area:1/1}\n.mk{width:80px;height:80px;background:var(--red);animation:lg .5s ease both,rd .5s 1s ease forwards,gone .4s 1.9s ease forwards}\n.mk svg{width:100%;height:100%}\n@keyframes lg{from{opacity:0;transform:scale(.6)}}\n@keyframes rd{to{border-radius:18px}}\n@keyframes gone{to{opacity:0;transform:scale(.7)}}\n.big{color:var(--red);opacity:0;animation:wmi .7s 2.2s ease forwards}\n.big .brand-logo{width:min(320px,80vw);height:auto}\n@keyframes wmi{from{opacity:0;transform:scale(.55)}to{opacity:1;transform:none}}\n.spin{position:absolute;bottom:70px;width:22px;height:22px;border:2px solid #2b8cf0;border-right-color:transparent;border-radius:50%;animation:rot .8s linear infinite}\n@keyframes rot{to{transform:rotate(360deg)}}\n.toast{position:absolute;left:50%;bottom:90px;transform:translateX(-50%);background:#333;color:#fff;padding:8px 16px;border-radius:18px;font-size:13px;z-index:60;animation:in .3s ease both}\n@media(prefers-reduced-motion:reduce){*{animation-duration:.01s!important;animation-delay:0s!important;transition-duration:.01s!important}}\n</style></head>\n<body><div id=\"app\">\n<div id=\"sp\"><div class=\"mk\"></div><div class=\"big\" id=\"big\"></div><div class=\"spin\"></div></div>\n<header id=\"top\"><button id=\"mn\" aria-label=\"Menu\"></button><div class=\"wm\" id=\"hw\"></div><button aria-label=\"Notifications\" id=\"bl\"></button></header>\n<section id=\"home\" class=\"pg ld\">\n<div class=\"sks\"><div class=\"wsw\"><div class=\"ws\"><div class=\"sk\" style=\"position:absolute;left:-20cqw;top:30cqw;width:40cqw;height:40cqw;border-radius:50%\"></div><div class=\"sk\" style=\"position:absolute;right:-20cqw;top:30cqw;width:40cqw;height:40cqw;border-radius:50%\"></div></div></div><div class=\"cwo\"><div class=\"sk\" style=\"aspect-ratio:2.54;border-radius:2cqw\"></div></div></div>\n<div class=\"real\"><div class=\"wsw\"><div class=\"ws\" id=\"ws\"></div></div>\n<div class=\"cwo\"><div class=\"flip\" id=\"fl\">\n<div class=\"fc fr\"><div class=\"ring\"></div><div class=\"ph avs\"></div><div class=\"si\"><div class=\"pill\" id=\"cn\"></div><div id=\"cg\"></div><div id=\"cc\"></div></div><button class=\"tap\" id=\"tp\">Tap</button></div>\n<div class=\"fc bk2\" id=\"cb\"></div></div></div></div></section>\n<section id=\"cal\" class=\"pg\"><p class=\"t1\">Timetable</p><p class=\"sub\">This screen was not in the recording. Add your content here.</p></section>\n<section id=\"att\" class=\"pg\"><p class=\"t1\">Attendance</p><p class=\"sub\">This screen was not in the recording. Add your content here.</p></section>\n<section id=\"prof\" class=\"pg ld\">\n<div class=\"sks\"><p class=\"t1\">Profile</p><div style=\"padding:20px 16px\"><div class=\"sk\" style=\"width:100px;height:100px;border-radius:50%\"></div></div><div id=\"psk\" style=\"padding:0 16px\"></div></div>\n<div class=\"real\"><p class=\"t1\" style=\"margin:0;background:var(--card)\">Profile</p>\n<div class=\"hero\"><p class=\"hello\" id=\"hl\"></p><div class=\"blob\"></div><div class=\"av avs\"></div></div>\n<div class=\"lk\"><button id=\"ed\"></button><button id=\"cpw\"></button></div>\n<div class=\"sheet\"><div class=\"tabs\"><button class=\"on\" data-k=\"p\">Personal Info</button><button data-k=\"e\">Educational Info</button></div><h3>Your Information</h3><div id=\"rows\"></div></div></div>\n<button class=\"fab\" id=\"lo\"></button></section>\n<div id=\"ep\"><div class=\"eh\"><button class=\"bk\" id=\"bk\"></button><h2>Edit Profile</h2></div><label class=\"pc\"><div class=\"avs\"></div>Change photo<input type=\"file\" accept=\"image/*\" hidden id=\"pf\"></label><div id=\"ef\"></div></div>\n<nav id=\"nav\"><svg class=\"bar\" id=\"bsv\"><path id=\"bp\" fill=\"#e01e26\"/></svg><div class=\"knob\" id=\"kn\"></div><div class=\"row\"></div></nav>\n<div id=\"dr\"><i></i><nav><div id=\"dw\"><img class=\"brand-logo\" src=\"data:image/png;base64,\" alt=\"Global Badariya Institute of Engineering & Management\"></div><a>Dashboard</a><a>Notices</a><a>Fees</a><a>Settings</a></nav></div>\n</div>\n<script>\nconst BRAND={logo:'data:image/png;base64,',alt:'Global Badariya Institute of Engineering & Management'};\nconst D={name:'chuti lulli',gno:'G/2089/BTECH/CSE DS/61',course:'Btech',branch:'CSE DS',father:'Father Name',mother:'Mother Name',dob:'01-Jan-2005',contact:'98765000000',email:'jamesbond@example.com',blood:'',samagra:'',rank:'27',att:'50%',photo:'data:image/jpeg;base64,',lap:''};\nconst P={home:'M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z',cal:'M3 8a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3zM8 3v4M16 3v4M3 11h18',chk:'M3 8a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3zM8 3v4M16 3v4M3 11h18M9 16l2 2 4-4',user:'M12 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM4 21c1-4 4-6 8-6s7 2 8 6',bell:'M6 16v-5a6 6 0 0 1 12 0v5l2 2H4zM10 21h4',menu:'M3 6h18M3 12h18M3 18h18',doc:'M7 3h7l5 5v10a3 3 0 0 1-3 3H7a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3zM8 12h8M8 16h5',edit:'M4 20h4L19 9l-4-4L4 16zM13 7l4 4',out:'M9 4H5a1 1 0 0 0-1 1v14a1 1 0 0 0 1 1h4M16 8l4 4-4 4M20 12H9',back:'M19 12H5M11 6l-6 6 6 6',key:'M4 5h9v14H4zM13 12h7'};\nconst ic=(n,s=22,c='currentColor')=>`<svg width=\"${s}\" height=\"${s}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"${c}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"${P[n]}\"/></svg>`;\nconst AV='<svg viewBox=\"0 0 80 80\"><rect width=\"80\" height=\"80\" fill=\"#e8d9d6\"/><circle cx=\"40\" cy=\"32\" r=\"14\" fill=\"#b9a4a0\"/><path d=\"M12 80c2-20 14-28 28-28s26 8 28 28z\" fill=\"#b9a4a0\"/></svg>';\nconst av=()=>D.photo?`<img src=\"${D.photo}\" alt=\"\">`:AV;\nconst $=s=>document.querySelector(s),app=$('#app');\n$('#big').innerHTML=`<img class=\"brand-logo\" src=\"${BRAND.logo}\" alt=\"${BRAND.alt}\">`;$('#hw').innerHTML=`<img class=\"brand-logo\" src=\"${BRAND.logo}\" alt=\"${BRAND.alt}\">`;\n$('.mk').innerHTML='<svg viewBox=\"0 0 80 80\"><path d=\"M57 29A19 19 0 1 0 59 42H41\" fill=\"none\" stroke=\"#fff\" stroke-width=\"7\"/><circle cx=\"40\" cy=\"40\" r=\"6\" fill=\"#f6a05a\"/></svg>';\n$('#mn').innerHTML=ic('menu',26);$('#bl').innerHTML=ic('bell',24);\n$('#ed').innerHTML='Edit Profile '+ic('edit',15,'#6b5bd2');$('#cpw').innerHTML='Change Password '+ic('key',15,'#2b8cf0');\n$('#lo').innerHTML=ic('out',18)+'Logout';$('#bk').innerHTML=ic('back',20);\nconst toast=t=>{const e=document.createElement('div');e.className='toast';e.textContent=t;app.append(e);setTimeout(()=>e.remove(),1800)};\n/* two half wheels */\nconst items=['Gate Pass','eLibrary','Book History','Notice','Issue Books','Fees','Library','Attendance','Apply Leave','Internship','Notification','Syllabus','Feedback','Complaint','CV/Resume','Training','Certificate','Activity','VT Letter','Exam Cell'];\nconst tiles=(from,flip)=>Array.from({length:20},(_,i)=>{const t=items[from+(i%10)],a=flip?-99-i*18:-81+i*18;return `<div class=\"tl\" style=\"--a:${a}deg;--i:${i};--f:${flip?180:0}deg\"><span>${t}</span></div>`}).join('');\n$('#ws').innerHTML=`<div class=\"wh wl\" data-direction=\"1\"><div class=\"dsk\"></div><div class=\"wheel\">${tiles(0,0)}</div><div class=\"wc\"><b id=\"rk\"></b>RANKING</div></div><div class=\"wh wr\" data-direction=\"-1\"><div class=\"dsk\"></div><div class=\"wheel\">${tiles(10,1)}</div><div class=\"wc\" style=\"right:2cqw\"><b id=\"at\"></b>ATTENDANCE</div></div>`;\n/* Each wheel owns its drag state and loops around its own arc: items leave the visible half and re-enter from the opposite end. Release with speed and it keeps turning, then settles on a slot. */\ndocument.querySelectorAll('.wh').forEach(wheel=>{const rotor=wheel.querySelector('.wheel'),direction=Number(wheel.dataset.direction),state={pointer:null,turn:0,startY:0,startTurn:0,lastY:0,lastT:0,v:0};\nconst set=t=>{state.turn=t;rotor.style.setProperty('--turn',t+'deg')};\nwheel.onpointerdown=e=>{if(e.button!==undefined&&e.button!==0)return;state.pointer=e.pointerId;state.startY=state.lastY=e.clientY;state.lastT=performance.now();state.v=0;state.startTurn=state.turn;rotor.style.transition='none';wheel.setPointerCapture(e.pointerId)};\nwheel.onpointermove=e=>{if(e.pointerId!==state.pointer)return;const radius=wheel.closest('.ws').clientWidth*.33,now=performance.now(),dt=Math.max(now-state.lastT,1),k=direction*180/radius;state.v=.8*state.v+.2*((e.clientY-state.lastY)*k/dt);state.lastY=e.clientY;state.lastT=now;set(state.startTurn+(e.clientY-state.startY)*k)};\nconst settle=e=>{if(e.pointerId!==state.pointer)return;state.pointer=null;const idle=performance.now()-state.lastT>80,v=idle?0:state.v,fling=Math.max(-720,Math.min(720,v*260));rotor.style.transition=Math.abs(fling)>18?'transform .8s cubic-bezier(.12,.8,.2,1)':'';set(Math.round((state.turn+fling)/18)*18)};\nwheel.onpointerup=settle;wheel.onpointercancel=settle});\n/* flip card: tap, or drag and release to toss it over */\nconst fl=$('#fl');let side=0,drag=null;fl._r=0;\n/* vertical flip: first click turns the card top-to-down (0 -> -180), next click turns it back down-to-up (-180 -> 0) */\nfunction flipTo(b,from){fl._r=b;side=b?1:0;const k=a=>`translateY(0) scale(1) rotateX(${a}deg)`,m=`translateY(-14px) scale(1.06) rotateX(${(from+b)/2}deg)`;fl.animate([{transform:k(from)},{transform:m,offset:.5},{transform:k(b)}],{duration:650,easing:'cubic-bezier(.3,.9,.3,1.08)'});fl.style.transform=k(b)}\nconst flipAngle=(a,dy)=>Math.max(-180,Math.min(0,a-dy/fl.offsetHeight*180));\nfl.onpointerdown=e=>{if(e.target.closest('button'))return;drag={y:e.clientY,a:fl._r,m:0,t:Date.now()};fl.setPointerCapture(e.pointerId)};\nfl.onpointermove=e=>{if(!drag)return;const dy=e.clientY-drag.y;drag.m=Math.max(drag.m,Math.abs(dy));fl.style.transform=`rotateX(${flipAngle(drag.a,dy)}deg)`};\nfl.onpointerup=e=>{if(!drag)return;const dy=e.clientY-drag.y,now=flipAngle(drag.a,dy),other=drag.a?0:-180;let b=drag.a;if(drag.m<6||Math.abs(now-drag.a)>45)b=other;drag=null;flipTo(b,drag?0:now)};\nfl.onpointercancel=()=>{if(!drag)return;const a=drag.a;drag=null;flipTo(a,a)};\n$('#tp').onclick=()=>flipTo(fl._r?0:-180,fl._r);\n\n/* profile rows */\nlet tab='p';\nObject.entries({enroll:'0000XX000000',bio:'00000',sem:'5',addr:'City, State',pcontact:'9000000000',cat:'General',adhar:'XXXX XXXX 0000',hob:'',str:'',weak:'',lap:'',p10:'00.0',p12:'00.0',ent:'JEE Main',cgpa:'0.00',back:'0'}).forEach(([k,v])=>{if(D[k]===undefined)D[k]=v});\nconst rowsP=()=>[['GNo',D.gno],['Biometric Id',D.bio],['Enrollment No',D.enroll],['Fathers Name',D.father],['Mothers Name',D.mother],['D.O.B',D.dob],['Contact No',D.contact],['Course',D.course+' ('+D.branch+')'],['Semester',D.sem],['Address',D.addr],['Parent Contact',D.pcontact],['Email',D.email],['Category',D.cat],['Blood Group',D.blood],['Adhar No',D.adhar],['Samagra Id',D.samagra],['Hobbies',D.hob],['Strength',D.str],['Weakness',D.weak],['Laptop',D.lap]];\nconst rowsE=()=>[['10th Percentage',D.p10],['12th Percentage',D.p12],['Entrance',D.ent],['Current CGPA',D.cgpa],['Backlogs',D.back]];\n/* everything bound to D redraws from here, so editing the profile updates the student card too */\nfunction R(){document.querySelectorAll('.avs').forEach(e=>e.innerHTML=av());$('#cn').textContent=D.name;$('#cg').textContent=D.gno;$('#cc').textContent=`${D.course} ( ${D.branch} )`;$('#rk').textContent=D.rank;$('#at').textContent=D.att;$('#hl').textContent='Hello, '+D.name;\n$('#cb').innerHTML=`Father Name: ${D.father}<br>Mother Name: ${D.mother}<br>Date Of Birth: ${D.dob}<br>Contact: ${D.contact}<br>Email: ${D.email}`;\n$('#rows').innerHTML=(tab=='p'?rowsP():rowsE()).map(r=>`<div class=\"ir\">${ic('doc',26)}<div><small>${r[0]}</small>${r[1]}</div></div>`).join('')}\ndocument.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{tab=b.dataset.k;document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('on',x==b));R()});\n$('#psk').innerHTML=Array(6).fill('<div style=\"display:flex;gap:14px;margin-bottom:18px\"><div class=\"sk\" style=\"width:40px;height:40px;border-radius:50%\"></div><div style=\"flex:1\"><div class=\"sk\" style=\"height:12px;border-radius:6px\"></div><div class=\"sk\" style=\"height:8px;border-radius:4px;margin-top:8px;width:70%\"></div></div></div>').join('');\n/* edit profile: every field maps to D, the form refills from D each time it opens, Save writes back to D and redraws every screen */\nconst F=[['name','Full Name',1],['gno','GNo',1],['course','Course',1],['branch','Branch',1],['father','Father Name'],['mother','Mother Name'],['dob','Date of Birth'],['contact','Contact Number'],['email','Email'],['bio','Biometric Id'],['enroll','Enrollment No'],['sem','Semester'],['addr','Address'],['pcontact','Parent Contact'],['cat','Category'],['adhar','Adhar No'],['samagra','Samagra ID'],['hob','Hobbies'],['str','Strength'],['weak','Weakness'],['lap','Laptop Brand'],['p10','10th Percentage'],['p12','12th Percentage'],['ent','Entrance'],['cgpa','Current CGPA'],['back','Backlogs']];\nconst fld=([k,l])=>`<div class=\"f\"><input id=\"f_${k}\" placeholder=\" \"><label>${l}</label></div>`;\nconst blood=`<div class=\"f\"><select id=\"f_blood\"><option value=\"\">Select Your Blood Group</option>${['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(b=>`<option>${b}</option>`).join('')}</select><label>Blood Group</label></div>`;\nconst at=k=>F.findIndex(f=>f[0]==k);\n$('#ef').innerHTML=F.slice(0,at('bio')).map(fld).join('')+blood+F.slice(at('bio'),at('lap')).map(fld).join('')+'<p class=\"sub\">Your Laptop Details Here!!!</p>'+fld(F[at('lap')])+'<p class=\"sub\">Educational Info</p>'+F.slice(at('p10')).map(fld).join('')+'<button class=\"sv\" id=\"sv\">Save</button>';\nconst ep=$('#ep'),fillForm=()=>{F.forEach(([k])=>$('#f_'+k).value=D[k]||'');$('#f_blood').value=D.blood||''};\nconst openEdit=()=>{fillForm();ep.scrollTop=0;ep.classList.add('on')},closeEdit=()=>ep.classList.remove('on');\nep.onscroll=()=>ep.style.setProperty('--fs',(32-14*Math.min(ep.scrollTop/50,1))+'px');\n$('#ed').onclick=openEdit;$('#bk').onclick=closeEdit;$('#cb').onclick=e=>{if(e.target.id=='eb')openEdit()};\n$('#pf').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{D.photo=r.result;R()};r.readAsDataURL(f)};\n$('#sv').onclick=()=>{const v=k=>$('#f_'+k).value.trim();\nfor(const [k,l,req] of F)if(req&&!v(k))return toast(l+' is required');\nif(v('contact')&&!/^\\d{10}$/.test(v('contact')))return toast('Contact must be 10 digits');\nif(v('pcontact')&&!/^\\d{10}$/.test(v('pcontact')))return toast('Parent contact must be 10 digits');\nif(v('email')&&!/^\\S+@\\S+\\.\\S+$/.test(v('email')))return toast('Enter a valid email');\nF.forEach(([k])=>D[k]=v(k));D.blood=$('#f_blood').value;R();closeEdit();toast('Profile saved')};\n$('#cpw').onclick=()=>toast('Change password (demo)');$('#lo').onclick=()=>toast('Logged out (demo)');$('#bl').onclick=()=>toast('No new notifications');\nconst dr=$('#dr');$('#mn').onclick=()=>dr.classList.add('on');dr.firstElementChild.onclick=()=>dr.classList.remove('on');\n/* bottom bar with a notch that slides to the active tab */\nconst pages=['home','cal','att','prof'],icons=['home','cal','chk','user'];let cur=0,cx=0,seen={};\nconst nav=$('#nav'),row=nav.querySelector('.row');\nrow.innerHTML=icons.map((n,i)=>`<button data-i=\"${i}\" aria-label=\"${pages[i]}\">${ic(n)}</button>`).join('');\nfunction draw(c){const w=nav.offsetWidth,h=nav.offsetHeight,y=0,d=44;$('#bsv').setAttribute('viewBox',`0 0 ${w} ${h}`);$('#bp').setAttribute('d',`M0 ${y}H${c-58}C${c-32} ${y} ${c-38} ${y+d} ${c} ${y+d}C${c+38} ${y+d} ${c+32} ${y} ${c+58} ${y}H${w}V${h}H0Z`);$('#kn').style.left=(c-22)+'px'}\nfunction place(anim){const to=(cur+.5)*nav.offsetWidth/4,from=cx,t0=performance.now();[...row.children].forEach((b,i)=>b.classList.toggle('on',i==cur));$('#kn').innerHTML=ic(icons[cur],24);if(!anim){cx=to;draw(cx);return}$('#kn').firstChild.animate([{transform:'scale(.4) rotate(-40deg)'},{transform:'none'}],{duration:380,easing:'ease-out'});(function f(t){const k=Math.min((t-t0)/380,1);cx=from+(to-from)*(1-Math.pow(1-k,3));draw(cx);if(k<1)requestAnimationFrame(f)})(t0)}\nfunction go(i){if(i==cur)return;app.style.setProperty('--d',i>cur?1:-1);cur=i;pages.forEach((p,k)=>$('#'+p).classList.toggle('on',k==i));$('#top').style.display=i==0?'flex':'none';if(window.ReactNativeWebView)window.ReactNativeWebView.postMessage(i===0?'home':i===3?'profile':'page');if(i==3&&!seen.p){seen.p=1;$('#prof').classList.add('ld');setTimeout(()=>$('#prof').classList.remove('ld'),1300)}place(1)}\nrow.onclick=e=>{const b=e.target.closest('button');if(b)go(+b.dataset.i)};\naddEventListener('resize',()=>place(0));\n/* boot */\nR();$('#home').classList.add('on');place(0);\nconst done=()=>{const s=$('#sp');if(!s)return;s.style.opacity=0;setTimeout(()=>s.remove(),500);setTimeout(()=>$('#home').classList.remove('ld'),1000)};\nsetTimeout(done,3600);$('#sp').onclick=done;\n</script><script>window.__gbHandleBack=()=>{if(ep.classList.contains(\"on\")){closeEdit();return true}if(dr.classList.contains(\"on\")){dr.classList.remove(\"on\");return true}if($(\"#sp\")){done();return true}return false};</script></body></html>";
